  0x8C: "\u013D", // Ľ - Latin Capital Letter L with Caron
  0x8D: "\u0145", // Ņ - Latin Capital Letter N with Cedilla
  0x8E: "\u014C", // Ō - Latin Capital Letter O with Macron
  0x8F: "\u0156", // Ŕ - Latin Capital Letter R with Acute
