  "E165": "\u00E8", // e + grave = è
  "E169": "\u00EC", // i + grave = ì
  "E16F": "\u00F2", // o + grave = ò
  "E175": "\u00F9", // u + grave = ù

  // Combining circumflex (0xE2)
  "E241": "\u00C2", // A + circumflex = Â
  "E245": "\u00CA", // E + circumflex = Ê
  "E249": "\u00CE", // I + circumflex = Î
  "E24F": "\u00D4", // O + circumflex = Ô
  "E255": "\u00DB", // U + circumflex = Û
  "E261": "\u00E2", // a + circumflex = â
  "E265": "\u00EA", // e + circumflex = ê
  "E269": "\u00EE", // i + circumflex = î
  "E26F": "\u00F4", // o + circumflex = ô
  "E275": "\u00FB", // u + circumflex = û

  // Combining tilde (0xE3)
  "E341": "\u00C3", // A + tilde = Ã
  "E34E": "\u00D1", // N + tilde = Ñ
  "E34F": "\u00D5", // O + tilde = Õ
  "E355": "\u0168", // U + tilde = Ũ
  "E361": "\u00E3", // a + tilde = ã
  "E36E": "\u00F1", // n + tilde = ñ
  "E36F": "\u00F5", // o + tilde = õ
