    const lines = utf8Text.split(/\r?\n/);
    const result = lines.map((line) => {
      if (line.match(/^1\s+CHAR\s+ANSEL/)) {
        return "1 CHAR UTF-8";
      }
      return line;
    });

    return result.join("\n");
  }

  // Unknown encoding, return as-is
  return content;
}

