let version = "5.5.1";
const gedcLines = header.tags.get("GEDC") || [];
if (gedcLines.length > 0) {
  const gedcIndex = header.lines.indexOf(gedcLines[0]);
  for (let i = gedcIndex + 1; i < header.lines.length; i++) {
